import pytest


def age_at(born: int, now: int) -> int:
    """Whole years from birth year `born` to current year `now`.

    Only years are given, so the result is `now - born`. The current year is
    a parameter and the clock is never read. Raises ValueError if `now` is
    earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_typical_age() -> None:
    assert age_at(1990, 2026) == 36


def test_born_this_year_is_zero() -> None:
    assert age_at(2026, 2026) == 0


def test_one_year_apart() -> None:
    assert age_at(2025, 2026) == 1


def test_century_span() -> None:
    assert age_at(1900, 2000) == 100


def test_result_is_int() -> None:
    assert isinstance(age_at(2000, 2020), int)


def test_negative_years_allowed_when_ordered() -> None:
    assert age_at(-100, 50) == 150


def test_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2027, 2026)


def test_far_future_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(3000, 1000)

